package com.client.multichatwindows.config.ui; import net.minecraft.network.chat.Component; public abstract class ScrollableDarkScreen extends DarkScreen { protected ScrollableDarkScreen(Component title){super(title);} @Override public boolean mouseScrolled(double mouseX,double mouseY,double horizontalAmount,double verticalAmount){int delta=(int)(-verticalAmount*16); if(onScroll(delta))return true; return super.mouseScrolled(mouseX,mouseY,horizontalAmount,verticalAmount);} protected boolean onScroll(int delta){return true;} }
